                    cache.popitem(last=False)
                cache[key] = value
        elif op[0] == 'get':
            key = op[1]
            if key in cache:
                value = cache[key]
                results.append(value)
                cache.move_to_end(key, last=True)
            else:
                results.append(-1)
    return results
